// Seven textbook algorithms, one per complexity class TempoBench fits.
//
// algorithms.rs and algorithms.py implement the same algorithms on the same
// inputs, generated by the same SplitMix64 stream, so all three print the same
// CHECKSUM for a given --algo and --n.  Only the hot section is timed; input
// generation and process startup are excluded through the TEMPOBENCH_MS marker.
//
//   g++ -O2 -std=c++17 -o algorithms algorithms.cpp
//   ./algorithms --algo merge_sort --n 100000

#include <algorithm>
#include <chrono>
#include <cstdint>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <string>
#include <vector>

using u64 = std::uint64_t;
using i64 = std::int64_t;

namespace {

constexpr u64 kSeed = 42;
constexpr u64 kHashMod = 1000000007;
constexpr int kQueries = 1 << 16;
constexpr long long kMaxCities = 24;  // Held-Karp needs n * 2^n table entries

struct SplitMix64 {
    u64 state;
    u64 next() {
        state += 0x9E3779B97F4A7C15ULL;
        u64 z = state;
        z = (z ^ (z >> 30)) * 0xBF58476D1CE4E5B9ULL;
        z = (z ^ (z >> 27)) * 0x94D049BB133111EBULL;
        return z ^ (z >> 31);
    }
    // Uniform enough for benchmark inputs; matches the other languages exactly.
    i64 below(u64 bound) { return static_cast<i64>((next() >> 11) % bound); }
};

// Optimisation barriers in the style of Google Benchmark.  `escape` makes the
// compiler assume the pointed-to memory is read and may be modified by someone
// else, and `opaque` hides a scalar's value, so a kernel whose inputs did not
// change between calls is still executed on every call rather than hoisted.
inline void escape(const void* p) { asm volatile("" : : "g"(p) : "memory"); }
template <typename T>
inline T opaque(T value) {
    asm volatile("" : "+r"(value));
    return value;
}

i64 hash_sequence(const std::vector<i64>& values) {
    u64 h = 0;
    for (i64 v : values) h = (h * 31 + static_cast<u64>(v)) % kHashMod;
    return static_cast<i64>(h);
}

std::vector<i64> random_values(SplitMix64& rng, int n, u64 bound) {
    std::vector<i64> values(n);
    for (auto& v : values) v = rng.below(bound);
    return values;
}

// Copy `input` rotated by a step that changes every call.  Sorting the very
// same array over and over lets the branch predictor learn its comparisons,
// which makes small inputs unrealistically fast; a rotation gives every call
// different subarrays to merge while the sorted result stays the same.
void rotated_copy(const std::vector<i64>& input, std::vector<i64>& out, std::size_t& shift) {
    shift = (shift + 7919) % input.size();
    std::rotate_copy(input.begin(), input.begin() + static_cast<std::ptrdiff_t>(shift), input.end(), out.begin());
}

// --- O(log n): binary search, a fixed batch of lookups ----------------------

i64 binary_search_count(const std::vector<i64>& sorted, const std::vector<i64>& queries) {
    i64 found = 0;
    for (i64 q : queries) {
        std::size_t lo = 0, hi = sorted.size();
        while (lo < hi) {
            std::size_t mid = lo + (hi - lo) / 2;
            if (sorted[mid] < q) lo = mid + 1; else hi = mid;
        }
        if (lo < sorted.size() && sorted[lo] == q) ++found;
    }
    return found;
}

// --- O(sqrt n): count divisors by trial division -----------------------------

i64 divisor_count(i64 n) {
    i64 count = 0;
    i64 d = 1;
    for (; d * d < n; ++d) {
        if (n % d == 0) count += 2;
    }
    if (d * d == n) ++count;
    return count;
}

// --- O(n): Kadane's maximum subarray sum ------------------------------------

i64 max_subarray(const std::vector<i64>& values) {
    i64 best = values[0], current = values[0];
    for (std::size_t i = 1; i < values.size(); ++i) {
        current = std::max(values[i], current + values[i]);
        best = std::max(best, current);
    }
    return best;
}

// --- O(n log n): top-down merge sort ----------------------------------------

void merge_sort_range(std::vector<i64>& a, std::vector<i64>& tmp, std::size_t lo, std::size_t hi) {
    if (hi - lo < 2) return;
    std::size_t mid = lo + (hi - lo) / 2;
    merge_sort_range(a, tmp, lo, mid);
    merge_sort_range(a, tmp, mid, hi);
    std::size_t i = lo, j = mid, k = lo;
    while (i < mid && j < hi) tmp[k++] = (a[j] < a[i]) ? a[j++] : a[i++];
    while (i < mid) tmp[k++] = a[i++];
    while (j < hi) tmp[k++] = a[j++];
    for (k = lo; k < hi; ++k) a[k] = tmp[k];
}

void merge_sort(std::vector<i64>& a) {
    std::vector<i64> tmp(a.size());
    merge_sort_range(a, tmp, 0, a.size());
}

// --- O(n^2): insertion sort --------------------------------------------------

void insertion_sort(std::vector<i64>& a) {
    for (std::size_t i = 1; i < a.size(); ++i) {
        i64 key = a[i];
        std::size_t j = i;
        while (j > 0 && a[j - 1] > key) {
            a[j] = a[j - 1];
            --j;
        }
        a[j] = key;
    }
}

// --- O(n^3): naive matrix multiplication -------------------------------------

void matrix_multiply(const std::vector<i64>& a, const std::vector<i64>& b, std::vector<i64>& c, int n) {
    std::fill(c.begin(), c.end(), 0);
    for (int i = 0; i < n; ++i)
        for (int k = 0; k < n; ++k) {
            i64 aik = a[i * n + k];
            for (int j = 0; j < n; ++j) c[i * n + j] += aik * b[k * n + j];
        }
}

// --- O(n^2 2^n): Held-Karp travelling salesman -------------------------------

i64 held_karp(const std::vector<i64>& dist, int n) {
    const i64 inf = INT64_MAX / 4;
    const std::size_t subsets = std::size_t{1} << n;
    std::vector<i64> dp(subsets * n, inf);
    dp[1 * n + 0] = 0;
    for (std::size_t mask = 1; mask < subsets; mask += 2) {
        for (int last = 0; last < n; ++last) {
            i64 cost = dp[mask * n + last];
            if (cost >= inf || !(mask >> last & 1)) continue;
            for (int next = 0; next < n; ++next) {
                if (mask >> next & 1) continue;
                std::size_t to = (mask | (std::size_t{1} << next)) * n + next;
                i64 candidate = cost + dist[last * n + next];
                if (candidate < dp[to]) dp[to] = candidate;
            }
        }
    }
    i64 best = inf;
    for (int last = 1; last < n; ++last)
        best = std::min(best, dp[(subsets - 1) * n + last] + dist[last * n + 0]);
    return n == 1 ? 0 : best;
}

// Copy the distance matrix with the cities shuffled.  The shortest tour is the
// same whatever the cities are called, but solving the very same matrix over
// and over lets the branch predictor learn it, as for the sorts above.
void relabel_cities(const std::vector<i64>& dist, std::vector<i64>& out, int n, SplitMix64& rng) {
    std::vector<int> perm(n);
    for (int i = 0; i < n; ++i) perm[i] = i;
    for (int i = n - 1; i > 0; --i) std::swap(perm[i], perm[rng.below(static_cast<u64>(i) + 1)]);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) out[i * n + j] = dist[perm[i] * n + perm[j]];
}

// --- Harness -----------------------------------------------------------------

using Clock = std::chrono::steady_clock;

double elapsed_ms(Clock::time_point start) {
    return std::chrono::duration<double, std::milli>(Clock::now() - start).count();
}

// Repeat `kernel` until at least `min_ms` of it has been timed and return the
// mean duration of one call.  `prepare` runs untimed before each call, e.g. to
// restore an input that the kernel sorts in place.  Fast kernels are thereby
// timed over many calls instead of one call near the clock's resolution.
template <typename Prepare, typename Kernel>
double measure(double min_ms, Prepare prepare, Kernel kernel) {
    double total = 0.0;
    long calls = 0;
    do {
        prepare();
        escape(&calls);
        auto start = Clock::now();
        kernel();
        escape(&calls);
        total += elapsed_ms(start);
        ++calls;
    } while (total < min_ms);
    return total / static_cast<double>(calls);
}

[[noreturn]] void usage(const char* message) {
    std::fprintf(stderr, "error: %s\nusage: algorithms --algo NAME --n N [--min-ms MS]\n", message);
    std::exit(2);
}

}  // namespace

int main(int argc, char** argv) {
    std::string algo;
    long long n = -1;
    double min_ms = 20.0;
    for (int i = 1; i < argc; ++i) {
        if (i + 1 >= argc) usage("missing value for an option");
        if (!std::strcmp(argv[i], "--algo")) algo = argv[++i];
        else if (!std::strcmp(argv[i], "--n")) n = std::atoll(argv[++i]);
        else if (!std::strcmp(argv[i], "--min-ms")) min_ms = std::atof(argv[++i]);
        else usage("unknown option");
    }
    if (algo.empty() || n < 1) usage("--algo and a positive --n are required");
    if (algo == "held_karp" && n > kMaxCities) usage("held_karp needs --n <= 24");

    SplitMix64 rng{kSeed};
    const int size = static_cast<int>(n);
    i64 checksum = 0;
    double ms = 0.0;
    auto nothing = [] {};

    // The checksum's address escapes, so storing into it can never be treated
    // as dead, and each kernel escapes its inputs before running.  Sequence
    // checksums are hashed afterwards, outside the timed section.
    escape(&checksum);
    if (algo == "binary_search") {
        std::vector<i64> sorted(size);
        for (int i = 0; i < size; ++i) sorted[i] = 2 * static_cast<i64>(i);
        std::vector<i64> queries = random_values(rng, kQueries, 2 * static_cast<u64>(size));
        ms = measure(min_ms, nothing, [&] {
            escape(sorted.data());
            escape(queries.data());
            checksum = binary_search_count(sorted, queries);
        });
    } else if (algo == "divisor_count") {
        ms = measure(min_ms, nothing, [&] { checksum = divisor_count(opaque(n)); });
    } else if (algo == "max_subarray") {
        std::vector<i64> values = random_values(rng, size, 2001);
        for (auto& v : values) v -= 1000;
        ms = measure(min_ms, nothing, [&] {
            escape(values.data());
            checksum = max_subarray(values);
        });
    } else if (algo == "merge_sort" || algo == "insertion_sort") {
        const std::vector<i64> input = random_values(rng, size, u64{1} << 30);
        std::vector<i64> work(input.size());
        auto sort = algo == "merge_sort" ? merge_sort : insertion_sort;
        std::size_t shift = 0;
        ms = measure(min_ms, [&] { rotated_copy(input, work, shift); }, [&] {
            sort(work);
            escape(work.data());
        });
        checksum = hash_sequence(work);
    } else if (algo == "matrix_multiply") {
        std::vector<i64> a = random_values(rng, size * size, 10);
        std::vector<i64> b = random_values(rng, size * size, 10);
        std::vector<i64> c(a.size());
        ms = measure(min_ms, nothing, [&] {
            escape(a.data());
            escape(b.data());
            matrix_multiply(a, b, c, size);
            escape(c.data());
        });
        checksum = hash_sequence(c);
    } else if (algo == "held_karp") {
        std::vector<i64> dist = random_values(rng, size * size, 100);
        for (auto& d : dist) d += 1;
        std::vector<i64> relabelled(dist.size());
        ms = measure(min_ms, [&] { relabel_cities(dist, relabelled, size, rng); }, [&] {
            escape(relabelled.data());
            checksum = held_karp(relabelled, opaque(size));
        });
    } else {
        usage("unknown --algo");
    }

    std::printf("CHECKSUM: %lld\n", static_cast<long long>(checksum));
    std::printf("TEMPOBENCH_MS: %.6f\n", ms);
    return 0;
}
